def anms(points, scores):
    points, scores = points[:3000], scores[:3000] # keep strongest
    radii = np.full(len(points), np.inf)  # strongest point stays unsuppressed
    for i in range(1, len(points)):
        stronger = scores[:i] > scores[i] / 0.9 # check which ones are stronger
        if stronger.any():
            radii[i] = ((points[:i][stronger] - points[i]) ** 2).sum(1).min()  # closest stronger distance
    return points[np.argsort(radii)[::-1][:500]]  # keep largest radii

def match(a, b):
    distance = ((a[:, None] - b[None, :]) ** 2).sum(2)  # compare every descriptor pair
    a_to_b = np.argsort(distance, axis=1)[:, :2]  # find two nearest candidates
    b_to_a = np.argsort(distance, axis=0)[:2]  # check reverse matching direction
    matches = []
    for i, (best, second) in enumerate(a_to_b):
        forward_ratio = distance[i, best] / distance[i, second]
        backward_ratio = distance[i, best] / distance[b_to_a[1, best], best]
        if forward_ratio < 0.7 and b_to_a[0, best] == i and backward_ratio < 0.7:
            matches.append((i, best))
    return np.array(matches)
